  (require 'gptel-openai)
  (let ((model (getenv "${ENV.model}"))
        (host (getenv "${ENV.host}"))
        (profile (getenv "${ENV.profile}"))
        (key (getenv "${ENV.key}")))
    (setq gptel-backend
