      (yeah-perm-rules-add rule)))
  (yeah-acp-serve))`;

/** Команда запуска ACP-сервера: Emacs в пакетном режиме и форма выше. */
export function acpCommand(launch: YeahLaunch): readonly [string, ...string[]] {
  return [launch.emacs, "-Q", "--batch", "--eval", LAUNCH_FORM];
